make_function=function(function_metadata,upvalues)
    local factory=F[function_metadata.id]
    if not factory then error("ANDROMEDA_UNKNOWN_PROTOTYPE: "..tostring(function_metadata.id),0) end
    return factory(function_metadata,upvalues)
end

-- Start the recovered application with the API slots used by its own code.
-- f96 clears the former loader seed cells at entry; it retains ffi and SHA256.

-- Shared implementation of the original per-call startup checkpoints.
local function new_tick(function_id)
    local instructions_left = startup_instruction_limit
    return function(pc)
        current_function, current_pc = function_id, pc
        if startup_active then
            instructions_left = instructions_left - 1
            if instructions_left <= 0 then
                error("ANDROMEDA_STARTUP_LIMIT: " .. function_id .. " pc=" .. pc, 0)
            end
            startup_poll_remaining = startup_poll_remaining - 1
            if startup_poll_remaining <= 0 then
                startup_poll_remaining = startup_poll_interval
                check_startup_clock()
            end
        end
    end
end

